#!/usr/bin/env python3
"""Required combined span check: new modules only, immutable log, clean aggregate."""
from pathlib import Path
import os,json,hashlib,subprocess
H=Path(__file__).resolve().parent;CHAT=H.parent;ROOT=H.parents[2];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
queue=[H/'iteration-audit.json'];seen={};objects={};sources={};external={}
while queue:
 p=queue.pop()
 if str(p) in seen:continue
 seen[str(p)]=sha(p);data=json.loads(p.read_text())
 for name,digest in data['source_sha256'].items():assert sha(ROOT/name)==digest,name;sources[name]=digest
 for name,digest in data.get('core_source_sha256',{}).items():assert sha(ROOT/name)==digest,name
 for name,digest in data.get('core_object_sha256',{}).items():assert sha(Path(name))==digest,name
 for name,digest in data.get('inherited_receipts_sha256',{}).items():assert sha(ROOT/name)==digest,name;queue.append(ROOT/name)
 for name,digest in data.get('new_dependency_object_sha256',{}).items():assert sha(Path(name))==digest,name;external[name]=digest
 for name,digest in data.get('objects_sha256',data.get('object_sha256',{})).items():
  path=Path(name);assert sha(path)==digest,name;module=name.rsplit('ChatResponseReferenceWork/',1)[1]
  if module in objects:assert objects[module][1]==digest,module
  objects[module]=(path,digest)
out=H/'Build/fixed-success-v1-final'
for module,(p,digest) in objects.items():
 target=out/'ChatResponseReferenceWork'/module
 if target.exists():assert sha(target)==digest,target
 else:target.parent.mkdir(parents=True,exist_ok=True);target.symlink_to(p.resolve())
for name,digest in external.items():
 assert sha(Path(name))==digest,name
 for src in (ROOT/'SignalReference/ProtoParseWork/FullParserV3Work/Build').rglob('*.olean'):
  dst=out/src.relative_to(ROOT/'SignalReference/ProtoParseWork/FullParserV3Work/Build')
  if not dst.exists():dst.parent.mkdir(parents=True,exist_ok=True);dst.symlink_to(src.resolve())
 module=name.rsplit('/ProtoParseWork/',1)[1];target=out/'ProtoParseWork'/module
 if target.is_symlink():target.unlink()
 target.parent.mkdir(parents=True,exist_ok=True);target.symlink_to(Path(name).resolve())
modules=['OpaqueValidity','OpaquePrefixValidity','OpaqueResume','FixedSource','FixedResume','OpaqueEvents','FixedKeyTerminal','FixedKeyValidity','FixedKeyControls','FixedKeyEntry','FixedKeyReady','FixedIteration'];files=[H/(m+'.lean') for m in modules]+[H/n for n in ['check_fixed_success.py','FIXED_SUCCESS.md']];before={str(p.relative_to(ROOT)):sha(p) for p in files}
token=hashlib.sha256(json.dumps(before,sort_keys=True).encode()).hexdigest()[:12];logpath=H/f'fixed-success-{token}-{os.getpid()}.log'
env=os.environ.copy();env['CHAT_RESPONSE_OUTPUT_ROOT']=str(out)
with logpath.open('x') as log:
 subprocess.run(['python3',str(CHAT/'check.py'),*['StreamingUnknownV1.'+m for m in modules]],env=env,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=180)
log=logpath.read_text();assert 'sorryAx' not in log and '_native.' not in log
for name in ['unknown_opaque_byte_valid','unknown_opaque_payload_prefix_valid','unknown_opaque_resumes','unknown_fixed_source_all','unknown_zero_recursion_source','actual_unknown_fixed_resumes','unknown_opaque_trace_exact','fixed_key_terminal_valid','unknown_native_fixed_key_valid','unknown_native_fixed_key_entry','actual_unknown_fixed_key_ready','actual_unknown_fixed_iteration','actual_unknown_fixed_loop_step']:assert name+"' depends on axioms:" in log
for name,digest in {**sources,**before}.items():assert sha(ROOT/name)==digest,name
for p,digest in objects.values():assert sha(p)==digest,p
(H/'fixed-success-audit.json').write_text(json.dumps({'candidate_only':True,'scope':'Actual unknown fixed32/fixed64 source all outcomes plus fit-success key/callback/parent-limit composition, exact source identity/drop suffix/cache/private counters and zero opaque events. Key entry derived from actual source key and actual fixed-width guard. Numeric rejection on underflow/overrun, length/group/header/full source joins remain OPEN; no full response claim.','aggregate_exit_code':0,'source_sha256':before,'inherited_receipts_sha256':{str(Path(p).relative_to(ROOT)):digest for p,digest in seen.items()},'inherited_source_count':len(sources),'inherited_object_count':len(objects),'kernel_log_path':str(logpath),'kernel_log_sha256':sha(logpath),'kernel_log':log,'new_dependency_object_sha256':external,'objects_sha256':{str(out/'ChatResponseReferenceWork/StreamingUnknownV1'/(m+'.olean')):sha(out/'ChatResponseReferenceWork/StreamingUnknownV1'/(m+'.olean')) for m in modules}},indent=2)+'\n')
print(f'Twelve actual fixed-field success modules PASS aggregate0; immutable log {logpath.name}; no unrelated native rerun')
